<?php
require_once __DIR__ . '/../../includes/layout.php'; require_role(['Admin']); check_csrf();
$entities = [
 'users'=>['title'=>'Users','table'=>'users','fields'=>['username'=>'Username','email'=>'Email','full_name'=>'Full Name','role_id'=>'Role ID','status'=>'Status'],'list'=>['id','username','email','full_name','role_id','status']],
 'students'=>['title'=>'Students','table'=>'students','fields'=>['user_id'=>'User ID','student_no'=>'Student No','course_id'=>'Course ID','section_id'=>'Section ID','year_level'=>'Year Level','birthdate'=>'Birthdate','gender'=>'Gender','address'=>'Address','phone'=>'Phone','gpa'=>'GPA','attendance_rate'=>'Attendance Rate','risk_level'=>'Risk Level'],'list'=>['id','student_no','course_id','section_id','year_level','gpa','attendance_rate','risk_level']],
 'teachers'=>['title'=>'Teachers','table'=>'teachers','fields'=>['user_id'=>'User ID','employee_no'=>'Employee No','department'=>'Department','specialization'=>'Specialization','phone'=>'Phone'],'list'=>['id','employee_no','department','specialization','phone']],
 'parents'=>['title'=>'Parents','table'=>'parents','fields'=>['user_id'=>'User ID','student_id'=>'Student ID','relationship'=>'Relationship','phone'=>'Phone'],'list'=>['id','user_id','student_id','relationship','phone']],
 'courses'=>['title'=>'Courses','table'=>'courses','fields'=>['code'=>'Code','name'=>'Name','description'=>'Description'],'list'=>['id','code','name','description']],
 'subjects'=>['title'=>'Subjects','table'=>'subjects','fields'=>['code'=>'Code','title'=>'Title','course_id'=>'Course ID','year_level'=>'Year Level','units'=>'Units','teacher_id'=>'Teacher ID'],'list'=>['id','code','title','course_id','year_level','units','teacher_id']],
 'sections'=>['title'=>'Sections','table'=>'sections','fields'=>['name'=>'Name','course_id'=>'Course ID','year_level'=>'Year Level','adviser_teacher_id'=>'Adviser Teacher ID'],'list'=>['id','name','course_id','year_level','adviser_teacher_id']],
 'school_years'=>['title'=>'School Years','table'=>'school_years','fields'=>['name'=>'Name','starts_at'=>'Start Date','ends_at'=>'End Date','is_active'=>'Is Active 1/0'],'list'=>['id','name','starts_at','ends_at','is_active']],
 'announcements'=>['title'=>'Announcements','table'=>'announcements','fields'=>['title'=>'Title','body'=>'Body','target_role'=>'Target Role'],'list'=>['id','title','target_role','created_at']],
 'schedules'=>['title'=>'Schedules','table'=>'schedules','fields'=>['subject_id'=>'Subject ID','section_id'=>'Section ID','teacher_id'=>'Teacher ID','day_of_week'=>'Day','start_time'=>'Start','end_time'=>'End','room'=>'Room'],'list'=>['id','subject_id','section_id','teacher_id','day_of_week','start_time','end_time','room']]
];
$entity = $_GET['entity'] ?? 'students'; if(!isset($entities[$entity])) $entity='students'; $cfg=$entities[$entity]; $table=$cfg['table'];
if ($_SERVER['REQUEST_METHOD']==='POST') {
    $action=$_POST['action'] ?? 'create';
    if ($entity==='users' && !empty($_POST['new_password'])) $_POST['password_hash'] = password_hash($_POST['new_password'], PASSWORD_DEFAULT);
    if ($action==='delete') { db()->prepare("DELETE FROM $table WHERE id=?")->execute([(int)$_POST['id']]); set_flash('success','Record deleted.'); log_activity($_SESSION['user_id'],'Deleted Record',"$entity ID " . (int)$_POST['id']); redirect('manage.php?entity='.$entity); }
    $fields = array_keys($cfg['fields']); if ($entity==='users' && isset($_POST['password_hash'])) $fields[]='password_hash';
    $data=[]; foreach($fields as $f){ if(isset($_POST[$f])) $data[$f]=trim((string)$_POST[$f]); }
    if ($entity==='announcements') $data['created_by']=$_SESSION['user_id'];
    if ($action==='update') { $id=(int)$_POST['id']; $sets=[]; $vals=[]; foreach($data as $k=>$v){$sets[]="$k=?";$vals[]=$v;} $vals[]=$id; db()->prepare("UPDATE $table SET ".implode(',',$sets)." WHERE id=?")->execute($vals); set_flash('success','Record updated.'); }
    else { $cols=array_keys($data); $q=implode(',',array_fill(0,count($cols),'?')); db()->prepare("INSERT INTO $table(".implode(',',$cols).") VALUES($q)")->execute(array_values($data)); set_flash('success','Record created.'); }
    log_activity($_SESSION['user_id'],'Saved Record',"$entity was saved."); redirect('manage.php?entity='.$entity);
}
$edit = isset($_GET['edit']) ? row("SELECT * FROM $table WHERE id=?", [(int)$_GET['edit']]) : null;
$data = rows("SELECT * FROM $table ORDER BY id DESC LIMIT 200");
render_header($cfg['title']);
?>
<div class="page-title"><div><h1><?= e($cfg['title']) ?></h1><p>Complete CRUD management module.</p></div><a class="btn btn-primary" href="manage.php?entity=<?= e($entity) ?>"><i class="fa-solid fa-plus me-2"></i>New</a></div>
<div class="row g-4"><div class="col-lg-4"><div class="panel"><div class="panel-title"><?= $edit?'Edit':'Create' ?> <?= e($cfg['title']) ?></div><form method="post"><?= csrf_field() ?><input type="hidden" name="action" value="<?= $edit?'update':'create' ?>"><?php if($edit): ?><input type="hidden" name="id" value="<?= e($edit['id']) ?>"><?php endif; ?><?php foreach($cfg['fields'] as $f=>$label): ?><div class="mb-3"><label class="form-label"><?= e($label) ?></label><?php if($f==='body' || $f==='description' || $f==='address'): ?><textarea name="<?= e($f) ?>" class="form-control" rows="3"><?= e($edit[$f] ?? '') ?></textarea><?php else: ?><input name="<?= e($f) ?>" class="form-control" value="<?= e($edit[$f] ?? '') ?>" <?= in_array($f,['code','name','username','student_no','employee_no','title'])?'required':'' ?>><?php endif; ?></div><?php endforeach; ?><?php if($entity==='users'): ?><div class="mb-3"><label class="form-label">Password for new/change user</label><input name="new_password" type="password" class="form-control" placeholder="Leave blank to keep old password"></div><?php endif; ?><button class="btn btn-primary w-100">Save</button></form></div></div><div class="col-lg-8"><div class="panel"><div class="panel-title">Records</div><div class="table-responsive"><table class="table table-hover"><thead><tr><?php foreach($cfg['list'] as $col): ?><th><?= e(strtoupper(str_replace('_',' ',$col))) ?></th><?php endforeach; ?><th>Action</th></tr></thead><tbody><?php foreach($data as $r): ?><tr><?php foreach($cfg['list'] as $col): ?><td><?= e($r[$col] ?? '') ?></td><?php endforeach; ?><td class="text-nowrap"><a class="btn btn-sm btn-outline-primary" href="manage.php?entity=<?= e($entity) ?>&edit=<?= e($r['id']) ?>"><i class="fa-solid fa-pen"></i></a><form method="post" class="d-inline"><?= csrf_field() ?><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?= e($r['id']) ?>"><button class="btn btn-sm btn-outline-danger confirm-delete"><i class="fa-solid fa-trash"></i></button></form></td></tr><?php endforeach; ?></tbody></table></div></div></div></div>
<?php render_footer(); ?>
